add_filter( 'woocommerce_related_products', 'perfectpixel_related_by_title_keyword', 20, 3 );

function perfectpixel_related_by_title_keyword( $related, $product_id, $args ) {
	$cache_key = 'perfectpixel_rel_kw_' . $product_id;
	$cached    = get_transient( $cache_key );
	if ( false === $cached ) {
		$words = preg_split( '/\s+/u', trim( wp_strip_all_tags( get_the_title( $product_id ) ) ) );
		$word  = $words ? $words[0] : '';
		$cached = array();
		if ( mb_strlen( $word ) >= 3 ) {
			$cached = get_posts(
				array(
					'post_type'      => 'product',
					'post_status'    => 'publish',
					's'              => $word,
					'fields'         => 'ids',
					'posts_per_page' => 20,
					'post__not_in'   => array( $product_id ),
					'no_found_rows'  => true,
				)
			);
		}
		set_transient( $cache_key, $cached, 12 * HOUR_IN_SECONDS );
	}
	return $cached ? $cached : $related;
}
